// Live cards for the profile README, regenerated by .github/workflows/cards.yml.
// No dependencies: Node 20 (fetch) plus the shared helpers in ./lib.
//   GITHUB_TOKEN=... node scripts/build-cards.mjs
//
// Writes assets/cards/{stats,languages,recent}-{dark,light}.svg. The SVGs hold no
// timestamp, so a run that finds nothing new produces identical files and no commit.
import { mkdirSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { THEMES, ACCENT, xmlEscape, num } from './lib/brand.mjs'
import { textPath, measure, truncate } from './lib/text.mjs'

const USER = process.env.PROFILE_USER || 'MaxDCoc'
const TOKEN = process.env.GITHUB_TOKEN || process.env.GH_TOKEN
if (!TOKEN) {
  console.error('Set GITHUB_TOKEN (the Actions token is enough).')
  process.exit(1)
}

const headers = {
  Authorization: `Bearer ${TOKEN}`,
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'profile-cards',
}

async function rest(path) {
  const res = await fetch(`https://api.github.com${path}`, { headers })
  if (!res.ok) throw new Error(`GitHub ${res.status} for ${path}: ${(await res.text()).slice(0, 200)}`)
  return res.json()
}

async function graphql(query, variables) {
  const res = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: { ...headers, 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, variables }),
  })
  const json = await res.json()
  if (!res.ok || json.errors) throw new Error(`GraphQL failed: ${JSON.stringify(json.errors ?? json).slice(0, 300)}`)
  return json.data
}

// ---------------------------------------------------------------- data

const repos = (await rest(`/users/${USER}/repos?type=owner&sort=pushed&per_page=100`)).filter(
  (r) => !r.fork && !r.archived && r.name.toLowerCase() !== USER.toLowerCase(),
)

const bytes = new Map()
for (const r of repos) {
  const langs = await rest(`/repos/${USER}/${r.name}/languages`)
  for (const [lang, n] of Object.entries(langs)) bytes.set(lang, (bytes.get(lang) ?? 0) + n)
}
const totalBytes = [...bytes.values()].reduce((a, b) => a + b, 0)
const topLangs = [...bytes.entries()]
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, n]) => ({ name, pct: (n / totalBytes) * 100 }))

const { user } = await graphql(
  `query ($login: String!) {
    user(login: $login) {
      contributionsCollection {
        totalCommitContributions
        totalPullRequestContributions
        contributionCalendar {
          totalContributions
          weeks { contributionDays { contributionCount } }
        }
      }
    }
  }`,
  { login: USER },
)
const cc = user.contributionsCollection
const weekly = cc.contributionCalendar.weeks
  .map((w) => w.contributionDays.reduce((a, d) => a + d.contributionCount, 0))
  .slice(-52)

const stats = [
  { n: cc.contributionCalendar.totalContributions, label: 'contributions' },
  { n: cc.totalCommitContributions, label: 'commits' },
  { n: cc.totalPullRequestContributions, label: 'pull requests' },
  { n: repos.length, label: 'public repos' },
]

const recent = repos.slice(0, 4).map((r) => ({
  name: r.name,
  description: r.description ?? '',
  language: r.language ?? '',
  pushed: r.pushed_at,
}))

const ago = (iso) => {
  const days = Math.floor((Date.now() - new Date(iso).getTime()) / 86400000)
  if (days < 1) return 'today'
  if (days === 1) return 'yesterday'
  if (days < 14) return `${days}d ago`
  if (days < 60) return `${Math.round(days / 7)}w ago`
  return `${Math.round(days / 30)}mo ago`
}

// ---------------------------------------------------------------- drawing

const T = (inst, s, o, fill) => {
  const { d, width } = textPath(inst, s, o)
  return { el: `<path d="${d}" fill="${fill}"/>`, width }
}

function frame(t, w, h, title, desc, body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="t d">
  <title id="t">${xmlEscape(title)}</title>
  <desc id="d">${xmlEscape(desc)}</desc>
  <rect x=".5" y=".5" width="${w - 1}" height="${h - 1}" rx="18" fill="${t.elev}" stroke="${t.line}"/>
  ${body}
</svg>
`
}

function statsCard(t) {
  const W = 392
  const H = 214
  const colW = (W - 48) / 4
  let body = T('semi', 'Last 12 months', { x: 24, y: 38, size: 14.5 }, t.accentText).el
  stats.forEach((s, i) => {
    const x = 24 + i * colW
    body += T('display', String(s.n), { x, y: 94, size: 46 }, t.ink).el
    body += T('ui', s.label, { x, y: 116, size: 12 }, t.ink2).el
  })
  const max = Math.max(...weekly, 1)
  const barW = (W - 48) / weekly.length
  let bars = ''
  weekly.forEach((c, i) => {
    const h = c ? Math.max(5, (c / max) * 44) : 3
    bars += `<rect x="${num(24 + i * barW)}" y="${num(186 - h)}" width="${num(barW - 1.6)}" height="${num(h)}" rx="1.4" fill="${c ? ACCENT : t.track}"/>`
  })
  body += bars
  body += T('ui', 'weekly contributions, last 52 weeks', { x: 24, y: 204, size: 11 }, t.ink2).el
  const desc = stats.map((s) => `${s.n} ${s.label}`).join(', ')
  return frame(t, W, H, 'GitHub activity, last 12 months', desc, body)
}

function languagesCard(t) {
  const W = 392
  const H = 214
  let body = T('semi', 'Top languages', { x: 24, y: 38, size: 14.5 }, t.accentText).el
  const trackX = 128
  const trackW = 186
  topLangs.forEach((l, i) => {
    const y = 72 + i * 25
    body += T('ui', l.name, { x: 24, y: y + 4.5, size: 13.5 }, t.ink).el
    body += `<rect x="${trackX}" y="${y - 4}" width="${trackW}" height="8" rx="4" fill="${t.track}"/>`
    body += `<rect x="${trackX}" y="${y - 4}" width="${num(Math.max(8, (l.pct / topLangs[0].pct) * trackW))}" height="8" rx="4" fill="${ACCENT}"/>`
    body += T('ui', `${l.pct.toFixed(1)}%`, { x: W - 24, y: y + 4.5, size: 13, anchor: 'end' }, t.ink2).el
  })
  body += T('ui', 'share of code in public repos', { x: 24, y: 204, size: 11 }, t.ink2).el
  const desc = topLangs.map((l) => `${l.name} ${l.pct.toFixed(1)}%`).join(', ')
  return frame(t, W, H, 'Top languages in public repositories', desc, body)
}

function recentCard(t) {
  const W = 800
  const ROW = 56
  const H = 62 + recent.length * ROW
  let body = T('semi', 'Recently active', { x: 24, y: 38, size: 14.5 }, t.accentText).el
  recent.forEach((r, i) => {
    const y = 62 + i * ROW
    body += `<path d="M24 ${y}H${W - 24}" stroke="${t.line}" stroke-width="1"/>`
    body += T('semi', r.name, { x: 24, y: y + 24, size: 15.5 }, t.ink).el
    if (r.description) {
      body += T('ui', truncate('ui', r.description, 13, 520), { x: 24, y: y + 43, size: 13 }, t.ink2).el
    }
    const when = T('ui', ago(r.pushed), { x: W - 24, y: y + 24, size: 13, anchor: 'end' }, t.ink2)
    body += when.el
    if (r.language) {
      const lw = measure('ui', r.language, 13)
      const lx = W - 24 - lw
      body += T('ui', r.language, { x: lx, y: y + 43, size: 13 }, t.ink).el
      body += `<circle cx="${num(lx - 10)}" cy="${y + 39}" r="4" fill="${ACCENT}"/>`
    }
  })
  const desc = recent.map((r) => `${r.name}, pushed ${ago(r.pushed)}`).join('; ')
  return frame(t, W, H, 'Recently active repositories', desc, body)
}

const outDir = fileURLToPath(new URL('../assets/cards/', import.meta.url))
mkdirSync(outDir, { recursive: true })
const cards = { stats: statsCard, languages: languagesCard, recent: recentCard }
for (const [name, draw] of Object.entries(cards)) {
  for (const theme of ['dark', 'light']) {
    writeFileSync(`${outDir}${name}-${theme}.svg`, draw(THEMES[theme]))
  }
  console.log(`${name}: dark + light`)
}
console.log(`stats: ${stats.map((s) => `${s.n} ${s.label}`).join(', ')}`)
console.log(`languages: ${topLangs.map((l) => `${l.name} ${l.pct.toFixed(1)}%`).join(', ')}`)
console.log(`recent: ${recent.map((r) => r.name).join(', ')}`)
